create table public.stocks (id bigint generated by default as identity primary key, symbol text not null unique, slug text not null unique, company_name text not null, exchange text, sector text, industry text, description text, logo_url text, website_url text, country text default 'US', market_cap numeric, currency text default 'USD', asset_type text not null default 'stock' check (asset_type in ('stock','etf','crypto')), is_active boolean not null default true, is_indexable boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.latest_quotes (stock_id bigint primary key references public.stocks(id) on delete cascade, price numeric, open numeric, high numeric, low numeric, previous_close numeric, change numeric, change_percent numeric, volume bigint, market_status text, quote_timestamp timestamptz, data_source text, updated_at timestamptz not null default now());
create table public.price_history (id bigint generated by default as identity primary key, stock_id bigint not null references public.stocks(id) on delete cascade, timeframe text not null, timestamp timestamptz not null, open numeric, high numeric, low numeric, close numeric, volume bigint, data_source text, unique(stock_id,timeframe,timestamp));
create table public.technical_indicators (stock_id bigint not null references public.stocks(id) on delete cascade, timeframe text not null, rsi numeric, macd numeric, macd_signal numeric, macd_histogram numeric, sma_20 numeric, sma_50 numeric, sma_100 numeric, sma_200 numeric, ema_20 numeric, ema_50 numeric, atr numeric, adx numeric, bollinger_upper numeric, bollinger_middle numeric, bollinger_lower numeric, stochastic numeric, obv numeric, volatility numeric, momentum numeric, support_level numeric, resistance_level numeric, calculated_at timestamptz not null default now(), primary key(stock_id,timeframe));
create table public.fundamentals (stock_id bigint not null references public.stocks(id) on delete cascade, fiscal_period text not null, market_cap numeric, enterprise_value numeric, revenue numeric, revenue_growth numeric, gross_profit numeric, operating_income numeric, net_income numeric, eps numeric, eps_growth numeric, pe_ratio numeric, forward_pe numeric, peg_ratio numeric, price_sales numeric, price_book numeric, debt_equity numeric, roe numeric, roa numeric, free_cash_flow numeric, dividend_yield numeric, report_date date, data_source text, updated_at timestamptz not null default now(), primary key(stock_id,fiscal_period));
create table public.earnings (id bigint generated by default as identity primary key, stock_id bigint not null references public.stocks(id) on delete cascade, earnings_date date, fiscal_period text, eps_estimate numeric, eps_actual numeric, eps_surprise numeric, revenue_estimate numeric, revenue_actual numeric, revenue_surprise numeric, data_source text, created_at timestamptz not null default now());
create table public.news (id bigint generated by default as identity primary key, stock_id bigint references public.stocks(id) on delete cascade, title text not null, summary text, url text, source text, published_at timestamptz, sentiment text check (sentiment in ('bullish','neutral','bearish')), sentiment_score numeric, relevance_score numeric, created_at timestamptz not null default now());
create table public.predictions (id bigint generated by default as identity primary key, stock_id bigint not null references public.stocks(id) on delete cascade, model_version text not null, prediction_time timestamptz not null default now(), horizon text not null check (horizon in ('24h','7d','30d','90d')), current_price numeric not null, predicted_price numeric, predicted_change_percent numeric, direction text check (direction in ('bullish','neutral','bearish')), confidence numeric check (confidence between 0 and 100), signal text, feature_summary jsonb, created_at timestamptz not null default now());
create table public.prediction_results (id bigint generated by default as identity primary key, prediction_id bigint not null references public.predictions(id) on delete cascade, stock_id bigint not null references public.stocks(id) on delete cascade, horizon text not null, predicted_price numeric, actual_price numeric, predicted_direction text, actual_direction text, absolute_error numeric, percentage_error numeric, hit boolean, evaluated_at timestamptz not null default now());
create table public.ai_articles (id bigint generated by default as identity primary key, stock_id bigint not null references public.stocks(id) on delete cascade, article_type text not null default 'market_analysis', title text not null, slug text, content text not null, summary text, model text, source_data_hash text, generated_at timestamptz not null default now(), updated_at timestamptz not null default now(), is_published boolean not null default false);
create table public.article_jobs (id bigint generated by default as identity primary key, stock_id bigint references public.stocks(id) on delete cascade, job_type text not null, status text not null default 'pending', priority integer not null default 0, attempts integer not null default 0, error_message text, scheduled_for timestamptz, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table public.market_snapshots (id bigint generated by default as identity primary key, symbol text not null, price numeric, change_percent numeric, timestamp timestamptz not null default now());
create index idx_price_history_stock_time on public.price_history(stock_id,timestamp desc); create index idx_news_stock_time on public.news(stock_id,published_at desc); create index idx_predictions_stock_time on public.predictions(stock_id,prediction_time desc); create index idx_jobs_status_priority on public.article_jobs(status,priority desc,scheduled_for); create index idx_stocks_slug on public.stocks(slug); create index idx_stocks_symbol on public.stocks(symbol);
alter table public.stocks enable row level security; alter table public.latest_quotes enable row level security; alter table public.price_history enable row level security; alter table public.technical_indicators enable row level security; alter table public.fundamentals enable row level security; alter table public.earnings enable row level security; alter table public.news enable row level security; alter table public.predictions enable row level security; alter table public.prediction_results enable row level security; alter table public.ai_articles enable row level security; alter table public.article_jobs enable row level security; alter table public.market_snapshots enable row level security;
create policy "public read active stocks" on public.stocks for select to anon, authenticated using (is_active and is_indexable); create policy "public read latest quotes" on public.latest_quotes for select to anon, authenticated using (true); create policy "public read price history" on public.price_history for select to anon, authenticated using (true); create policy "public read technical indicators" on public.technical_indicators for select to anon, authenticated using (true); create policy "public read fundamentals" on public.fundamentals for select to anon, authenticated using (true); create policy "public read earnings" on public.earnings for select to anon, authenticated using (true); create policy "public read news" on public.news for select to anon, authenticated using (true); create policy "public read predictions" on public.predictions for select to anon, authenticated using (true); create policy "public read prediction results" on public.prediction_results for select to anon, authenticated using (true); create policy "public read published articles" on public.ai_articles for select to anon, authenticated using (is_published); create policy "public read market snapshots" on public.market_snapshots for select to anon, authenticated using (true);
